def hydrate_time(nanoseconds, tz=None):
    seconds = nanoseconds // 10**9
    nanos_remainder = nanoseconds % 10**9
    time_obj = time(seconds % (24 * 3600), seconds // 3600 % 60, seconds // 3600 % 24)
    if nanos_remainder != 0:
        time_obj = time_obj + timedelta(microseconds=nanos_remainder // 1000)
    if tz is not None:
        time_obj = time_obj.replace(tzinfo=tz)
    return time_obj

