    """Reduce a list of base classes to its ordered minimum equivalent"""
    # First, remove consecutive duplicates while preserving order
    deduped = []
    for cls in classes:
        if not deduped or cls is not deduped[-1]:
            deduped.append(cls)

    # Now remove any class that is a subclass of another class in the list
    # A class should be kept only if it is not a proper subclass of any other class in the list
    minimal = []
    for i, cls in enumerate(deduped):
