def fill(self, coord, weight=1):
        # Find the bin index for the given coord
        if len(self.edges) == 0:
            return
        if coord < self.edges[0] or coord >= self.edges[-1]:
            return
        # Binary search to find the bin
        left, right = 0, len(self.edges) - 1
        while left < right:
            mid = (left + right) // 2
            if coord < self.edges[mid + 1]:
                right = mid
            else:
                left = mid + 1
        self.counts[left] += weight
        self.sum_weights += weight

