def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.

            .. code:: python

                # Example:
                labels = {
                    "key1": "valid",
                    "key2": ["invalid"],
                    "$$": "invalid",
                    True: True,
                }
                try:
                    _validate_labels(labels)
                except ValidationError as err:
                    assert err.messages == [
                        {"['invalid']": 'expected string or bytes-like object'},
                        {'$$': "Label key '$$' does not match the regex [...]"},
                        {'True': 'expected string or bytes-like object'},
                        {'True': 'expected string or bytes-like object'},
                    ]
    """
    import re

    # Define the regular expressions as per typical label validation rules
    label_key_regex = re.compile(r'^[A-Za-z0-9._-]{1,255}$')
    label_value_regex = re.compile(r'^[A-Za-z0-9._-]{1,255}$')

    errors = []

    for key, value in labels.items():
        # Validate key
        try:
            if not isinstance(key, (str, bytes)):
                raise TypeError('expected string or bytes-like object')
            key_str = key.decode('utf-8') if isinstance(key, bytes) else key
            if not label_key_regex.match(key_str):
                errors.append({str(key): f"Label key '{key_str}' does not match the regex {label_key_regex.pattern}"})
        except TypeError as e:
            errors.append({str(key): str(e)})

        # Validate value
        try:
            if not isinstance(value, (str, bytes)):
                raise TypeError('expected string or bytes-like object')
            value_str = value.decode('utf-8') if isinstance(value, bytes) else value
            if not label_value_regex.match(value_str):
                errors.append({str(value): "Label value " + repr(value_str) + " does not match the regex " + label_value_regex.pattern})
        except TypeError as e:
            errors.append({str(value): str(e)})

    if errors:
        raise ValidationError(messages=errors)


    class ValidationError(Exception):
        def __init__(self, messages=None):
            self.messages = messages or []
            super().__init(f"Validation failed: {self.messages}")

