def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    spec_version = self.spec_version
    if extract_spec_version:
        inv_type = inventory.get('type')
        if inv_type == 'DEPRECATED':
            spec_version = '1.0'
        elif inv_type == 'INVENTORY':
            spec_version = '1.1'
        elif inv_type == 'INVENTORY_DATA':
            spec_version = '1.2'

    errors = []

    # Check for required top-level fields based on spec version
    if spec_version in ['1.0', '1.1', '1.2']:
        required_fields = ['id', 'type', 'date']
        for field in required_fields:
            if field not in inventory:
                errors.append(f"Missing required field: {field}")

    # Validate id field if present
    if 'id' in inventory:
        inv_id = inventory['id']
        if not isinstance(inv_id, str) or not inv_id:
            errors.append("Field 'id' must be a non-empty string")

    # Validate type field if present
    if 'type' in inventory:
        inv_type = inventory['type']
        if not isinstance(inv_type, str) or not inv_type:
            errors.append("Field 'type' must be a non-empty string")

    # Validate date field if present
    if 'date' in inventory:
        inv_date = inventory['date']
        if not isinstance(inv_date, str):
            errors.append("Field 'date' must be a string")
        else:
            # Basic date format check (ISO 8601)
            try:
                from datetime import datetime
                datetime.fromisoformat(inv_date.replace('Z', '+00:00'))
            except ValueError:
                errors.append("Field 'date' must be a valid ISO 8601 date string")

    # version 1.1+ specific checks
    if spec_version in ['1.1', '1.2']:
        if 'products' in inventory:
            products = inventory['products']
            if not isinstance(products, list):
                errors.append("Field 'products' must be a list")
            else:
                for i, product in enumerate(products):
                    if not isinstance(product, dict):
                        errors.append(f"Product at index {i} must be a dictionary")
                        continue
                    # Check required product fields
                    for field in ['category', 'count']:
                        if field not in product:
                            errors.append(f"Product at index {i} missing required field: {field}")

    if 'errors' in inventory:
        errors_list = inventory['errors']
        if not isinstance(errors_list, list):
            errors.append("Field 'errors' must be a list")
        else:
            for i, err in enumerate(errors_list):
                if not isinstance(err, dict):
                    errors.append(f"Error at index {i} must be a dictionary")

    return errors

