    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Check that the prior version does not have any items that are deleted in the current version
    for item in prior.items:
        if item not in self.items:
            raise ValueError(f"Item {item} in prior version does not exist in current version")

    # Check that the count of items in the prior version is less than or equal to the current version
    if len(prior.items) > len(self.items):
        raise ValueError("Prior version has more items than current version")

    # Check that for all common items, the count in the prior version is less than or equal to the current version
    for item in prior.items:
        if item in self.items and prior.items[item] > self.items[item]:
            raise ValueError(f"Count of item {item} in prior version is greater than current version")

