def files_list_from_zipfile(zip_path):
    import zipfile

    def _extract_name(path):
        # Remove any leading directory (the root folder of the zip)
        parts = path.split('/')
        if len(parts) > 1:
            return '/'.join(parts[1:])
        else:
            return path

    with zipfile.ZipFile(zip_path, 'r') as zf:
        names = zf.namelist()
        # Filter out directories (names ending with '/')
        files = [name for name in names if not name.endswith('/')]
        # Apply the extraction logic to get paths relative to the first common folder
        # Find the common root prefix (usually the first element of the first path)
        if files:
            first_parts = files[0].split('/')
            if len(first_parts) > 1:
                root = first_parts[0]
                # Filter out any files not in this root
                files = [f for f in files if f.startswith(root + '/')]
                # Convert to relative paths with root prepended
                result = []
                for f in files:
                    # f looks like "root/file_path"
                    # We want "root/filepath" 
                    result.append(f)
                return result
            else:
                return files
        else:
            return []

