    """
    Return a pretty formatted representation of self.
    """
    ind = '  ' * indent
    result = ind + self.__class__.__name__ + ':\n'
    for key, value in self.__dict__.items():
        if isinstance(value, (list, tuple)):
            result += ind + '  {}: [\n'.format(key)
            for item in value:
                if hasattr(item, 'pretty'):
                    result += '  ' + indent + item.pretty(indent + 2, debug)
                else:
                    result += '  ' * (indent + 2) + repr(item) + ',\n'
            result += ind + '  ]\n'
        elif isinstance(value, dict):
            result += ind + '  {}: {\n'.format(key)
            for k2, v2 in value.items():
                if hasattr(v2, 'pretty'):
                    result += '  ' * (indent + 1) + '{}: '.format(k2) + v2.pretty(indent + 2, debug)
                else:
                    result += '  ' * (indent + 1) + '{}: '.format(k2) + repr(v2) + '\n'
            result += ind + '  }\n'
        else:
            if hasattr(value, 'pretty'):
                result += ind + '  {}: '.format(key) + value.pretty(indent + 1, debug)
            else:
                result += ind + '  {}: {}\n'.format(key, repr(value))
    if debug:
        result += ind + '  <debug info>:\n'
        for attr in dir(self):
            if not attr.startswith('_') and not callable(getattr(self, attr)):
