def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import sys
    import subprocess

    if isinstance(commands, str):
        commands = [commands]

    # Combine all commands into a single command line
    full_command = " ".join(commands + args)
    if verbose:
        sys.stdout.write("# " + full_command + "\n")

    try:
        if hide_stderr:
            stdout = subprocess.PIPE
            stderr = subprocess.DEVNULL
        else:
            stdout = subprocess.PIPE if not verbose else None
            stderr = subprocess.PIPE if not verbose else None

        process = subprocess.Popen(
            full_command,
            stdout=stdout,
            stderr=stderr,
            cwd=cwd,
            env=env,
            shell=True
        )
        stdout, stderr = process.communicate()
        if process.returncode != 0:
            if stderr:
                sys.stderr.write(stderr.decode('utf-8'))
            raise RuntimeError("Command failed: " + full_command)
        if not hide_stderr and stderr:
            sys.stderr.write(stderr.decode('utf-8'))
    except Exception as e:
        print("Error running command: {}".format(str(e)), file=sys.stderr)
        raise e

