def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    from ruamel.yaml.nodes import ScalarNode, MappingNode

    def is_mapping_node(node):
        return isinstance(node, MappingNode)

    def get_key_value(node):
        if isinstance(node, ScalarNode):
            return node.value
        return None

    def merge_nodes(existing, new):
        if is_mapping_node(existing) and is_mapping_node(new):
            existing_keys = {get_key_value(k): i for i, (k, v) in enumerate(existing.value)}
            for new_key, new_val in new.value:
                key_val = get_key_value(new_key)
                if key_val in existing_keys:
                    idx = existing_keys[key_val]
                    existing_key, existing_val = existing.value[idx]
                    existing.value[idx] = (existing_key, merge_nodes(existing_val, new_val))
                else:
                    existing.value.append((new_key, new_val))
                existing_keys[key_val] = len(existing.value) - 1
            return existing
        else:
            return new

    if not nodes:
        return []

    merged = {}
    order = []

    for key, value in nodes:
        key_val = get_key_value(key)
        if key_val in merged:
            merged[key_val] = merge_nodes(merged[key_val], value)
        else:
            merged[key_val] = value
            order.append(key_val)

    result = []
    for key_val in order:
        # We need to reconstruct the original key node
        # We used the value as the identifier, but we need the actual ScalarNode
        # Let's store the key node as well or find it
        pass

    # Let's redo with storing key nodes
    merged_nodes = {}
    order = []

    for key, value in nodes:
        key_val = get_key_value(key)
        if key_val in merged_nodes:
            merged_nodes[key_val] = (key, merge_nodes(merged_nodes[key_val][1], value))
        else:
            merged_nodes[key_val] = (key, value)
            order.append(key_val)

    result = []
    for key_val in order:
        key, value = merged_nodes[key_val]
        result.append((key, value))

