def _parse_image_ref(image_href: str) -> Tuple[str, str, bool]:
    parsed = urllib.parse.urlparse(image_href)

    if parsed.scheme == 'http':
        use_ssl = False
    elif parsed.scheme == 'https':
        use_ssl = True
    else:
        raise ValueError(f"Unsupported scheme: {parsed.scheme}")

    # The image ID is constructed from the netloc and the path
    # The path typically starts with /, so we want to include it
    # The expected format is likely "netloc/path"

    # Remove the leading slash if present in path
    path = parsed.path
    if path.startswith('/'):
        path = path[1:]

    # If path is empty, then we only have netloc
    image_id = path if path else ''

    return (f"{parsed.netloc}/{path}" if path else parsed.netloc, parsed.netloc, use_ssl)

