def make_array(shape, dtype=np.dtype("float32")):
    """
    Function to create an array with shape and dtype.

    Parameters
    ----------
    shape : tuple
        shape of the array to create
    dtype : `numpy.dtype`
        data-type of the array to create
    """
    if not isinstance(shape, tuple):
        raise TypeError("shape must be a tuple")
    if len(shape) == 0:
        return np.empty((), dtype=dtype)

    # Validate that shape elements are non-negative integers
    for dim in shape:
        if not isinstance(dim, (int, np.integer)):
            raise TypeError(f"Shape dimensions must be integers, got {type(dim)}")
        if dim < 0:
            raise ValueError(f"Shape dimensions must be non-negative, got {dim}")

    return np.empty(shape, dtype=dtype)

