def load_configurations(config_filenames, overrides=None, resolve_env=True):
    import logging

    import os

    import re

    import json

    import yaml

    from collections import OrderedDict
    config_results = {}
    parse_errors = []
    if overrides is None:
        overrides = {}

    for config_filename in config_filenames:
        # Open the file and read its contents.
        try:
            with open(config_filename, 'r') as f:
                file_contents = f.read()
        except (IOError, OSError) as e:
            error_msg = "Could not open configuration file {}: {}".format(config_filename, str(e))
            record = logging.LogRecord(
                name="load_configurations",
                level=logging.ERROR,
                pathname="load_configurations",
                lineno=0,
                msg=error_msg,
                args=None,
                exc_info=None
            )
            parse_errors.append(record)
            continue

        # Resolve environment variables if requested
        if resolve_env:
            def resolve_placeholder(match):
                return os.environ.get(match.group(1), match.group(0))
            file_contents = re.sub(r'\$\{([A-Za-z0-9_]+)\}', resolve_placeholder, file_contents)

        # Determine the file format based on the file extension
        file_extension = os.path.splitext(config_filename)[1].lower()
        config = None
        try:
            if file_extension in ['.yml', '.yaml']:
                # Load YAML configuration
                config = yaml.safe_load(file_contents)
                if config is None:
                    config = {}
            elif file_extension == '.json':
                # Load JSON configuration
                config = json.loads(file_contents, object_pairs_hook=OrderedDict)
                if config is None:
                    config = {}
            else:
                # Assume it's YAML if no known extension
                config = yaml.safe_load(file_contents)
                if config is None:
                    config = {}
        except Exception as e:
            error_msg = "Failed to parse configuration file {}: {}".format(config_filename, str(e))
            record = logging.LogRecord(
                name="load_configurations",
                level=logging.ERROR,
                pathname="load_configurations",
                lineno=0,
                msg=error_msg,
                args=None,
                exc_info=None
            )
            parse_errors.append(record)
            continue

        # Apply overrides if any
        if overrides:
            config.update(overrides)

        config_results[config_filename] = config

    return config_results, parse_errors

