def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    import xml.etree.ElementTree as ElementTree

    def parse_json(document: str) -> Dict:
        data = json.loads(document)
        links = data.get('links', [])
        result = {}
        for link in links:
            if link.get('relation') in ('describedby', 'self', 'http://webfinger.net/rel/profile-page'):
                result[link['relation']] = link.get('href')
        return result

    def parse_xrd(document: str) -> Dict:
        root = ElementTree.fromstring(document)
        ns = {'x': 'http://docs.oasis-open.org/webfinger/xrd/1.0'}
        aliases = root.findall('.//x:alias', ns)
        result = {}
        result['aliases'] = [alias.text for alias in aliases]
        properties = root.findall('.//x:property', ns)
        for prop in properties:
            name = prop.get('name')
            result[name] = prop.text
        links = root.findall('.//x:link', ns)
        for link in links:
            rel = link.get('rel')
            href = link.get('href')
            if rel == 'self':
                result['self'] = href
            elif rel == 'describedby':
                result['describedby'] = href
        return result

    # Try JSON first
    try:
        json.loads(document)
        return parse_json(document)
    except json.JSONDecodeError:
        pass

    # Try XRD
    try:
        root = ElementTree.fromstring(document)
        return parse_xrd(document)
    except ElementTree.ParseError:
        pass

    raise ValueError("Invalid webfinger format")

