    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json

    import xml.etree.ElementTree as ET

    from typing import Dict
    document = document.strip()
    result = {}

    if document.startswith('{'):
        # Try JSON format first
        try:
            data = json.loads(document)
            # Extract subject
            subject = data.get('subject', '')
            aliases = data.get('aliases', [])
            links = data.get('links', [])

            result['subject'] = subject
            result['aliases'] = aliases
            result['links'] = []

            for link in links:
                if link.get('rel') == 'http://diaspora.org/ns/atom#author':
                    result['links'].append({
                        'rel': 'http://diaspora.org/ns/atom#author',
                        'href': link.get('href', ''),
                        'type': link.get('type', ''),
                        'title': link.get('title', '')
                    })
                elif link.get('rel') == 'lrdd':
                    result['links'].append({
                        'rel': 'lrdd',
                        'href': link.get('href', ''),
                        'type': link.get('type', ''),
                        'title': link.get('title', '')
                    })
        except json.JSONDecodeError:
            pass  # Fall through to XRD parsing

    # Try XRD format if JSON failed or wasn't tried
    if not result:
        try:
            # Handle the xmlns in the XRD document
            root = ET.fromstring(document)

            # Remove namespace prefixes for easier handling
            # We'll use namespace-aware parsing
            ns = {'xrd': 'http://docs.oasis-open.org/ns/xri/xrd-1.0'}

            subject = root.find('xrd:Subject', ns)
            if subject is not None:
                result['subject'] = subject.text or ''

            aliases = []
            alias_elem = root.find('xrd:Alias', ns)
            if alias_elem is not None:
                aliases = [alias_elem.text]
            else:
                # Look for all alias elements
                for alias in root.findall('.//{http://docs.oasis-open.org/ns/xri/xrd-1.0}Alias'):
                    aliases.append(alias.text)
            result['aliases'] = aliases

            links = []
            for link in root.findall('.//{http://docs.oasis-open.org/ns/xri/xrd-1.0}Link'):
                link_data = {
                    'rel': link.get('rel', ''),
                    'href': link.get('href', ''),
                    'type': link.get('type', ''),
                    'title': link.get('title', '')
                }
                links.append(link_data)

            result['links'] = links

        except ET.ParseError:
            raise ValueError("Unable to parse webfinger document as JSON or XRD")

    return result

