    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json

    from xml.etree import ElementTree

    from typing import Dict
    # Try to parse as JSON first
    try:
        data = json.loads(document)
        if 'links' in data:
            result = {'links': []}
            for link in data['links']:
                if 'rel' in link and 'alias' in link:
                    if link['rel'] == 'diaspora-public-address':
                        result['links'].append({
                            'alias': link['alias'],
                            'rel': 'diaspora-public-address',
                            'url': link.get('href', '')
                        })
                    elif link['rel'] == 'http://dnsid.org/ns#xrn-alias':
                        result['links'].append({
                            'alias': link['alias'],
                            'rel': link['rel'],
                            'url': link.get('href', '')
                        })
            return result
        elif 'subject' in data:
            result = {'subject': data['subject']}
            if 'links' in data:
                result['links'] = [
                    {
                        'alias': link.get('alias', ''),
                        'rel': link.get('rel', ''),
                        'url': link.get('href', '')
                    }
                    for link in data['links']
                ]
            return result
    except json.JSONDecodeError:
        pass

    # Try to parse as XRD (XML)
    try:
        root = ElementTree.fromstring(document)
        ns = {'xrd': 'http://docs.oasis-open.org/ns/xrd-1.0'}

        result = {}

        # Check for alias elements
        aliases = root.findall('.//xrd:Alias', ns)
        if aliases:
            result['subject'] = aliases[0].text

        # Find all Link elements
        result['links'] = []
        for link in root.findall('.//xrd:Link', ns):
            alias = link.find('xrd:Alias', ns)
            alias_text = alias.text if alias is not None else None
            rel = link.get('rel', '')
            href = link.get('href', '')

            if alias_text and rel:
                result['links'].append({
                    'alias': alias_text,
                    'rel': rel,
                    'url': href
                })

        return result
    except ElementTree.ParseError:
        pass

    # If neither JSON nor XRD could be parsed, return empty dict or raise error
    return {}

