def retrieve_diaspora_host_meta(host):
    # Construct the node-info path
    import requests
    node_info_url = f"http://{host}/.well-known/nodeinfo"

    # Send a request to check if nodeinfo is available
    try:
        response = requests.get(node_info_url, timeout=10, headers={'User-Agent': 'Diaspora/0.5.0 ( compatibility nodeinfo check )'})
        if response.status_code == 200:
            nodeinfo_link = response.headers.get("Link")
            if nodeinfo_link:
                # Try to find nodeinfo version 2.0
                parts = [part.strip() for part in nodeinfo_link.split(";")]
                if any('rel="http://nodeinfo.diaspora.cc/ns#version/2.0"' in part for part in parts):
                    # Extract the URL from the Link header
                    import re
                    match = re.search('<(.*?)(>|\?">', nodeinfo_link)
                    if match:
                        nodeinfo_url = match.group(1)
                        nodeinfo_response = requests.get(nodeinfo_url, timeout=10, headers={'User-Agent': 'Diaspora/0.5.0 ( compatibility nodeinfo check )'})
                        if nodeinfo_response.status_code == 200:
                            return nodeinfo_response.json()
    except:
        pass

    # Fallback to .well-known/host-meta
    host_meta_url = f"http://{host}/.well-known/host-meta"

    # Try http first
    try:
        response = requests.get(host_meta_url, timeout=10, headers={'User-Agent': 'Diaspora/0.5.0 ( compatibility nodeinfo check )'})
        if response.status_code == 200:
            return response.content
    except:
        pass

    # Try https
    host_meta_url_https = f"https://{host}/.well-known/host-meta"
    try:
        response = requests.get(host_meta_url_https, timeout=10, headers={'User-Agent': 'Diaspora/0.5.0 ( compatibility nodeinfo check )'})
        if response.status_code == 200:
            return response.content
    except:
        pass

