                                     args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    required_args = []
    for opt in options_spec:
        required_when = opt.get('required_when')
        if required_when:
            matched = False
            for condition in required_when:
                if isinstance(condition, dict):
                    arg_name = condition.get('name')
                    expected_value = condition.get('value')
                    if arg_name in args and args[arg_name] == expected_value:
                        matched = True
                        break
                elif isinstance(condition, (list, tuple)):
                    # Assuming condition is a tuple of (arg_name, expected_value)
